def make_entry(idx_offset, raw):
    # Handle either 12-element or 13-element tuples (some earlier entries may lack artist_gender/nationality)
    if len(raw) == 12:
        title, artist, year, medium, movement, style, subject, color_palette, museum, description, historical_significance, artist_gender = raw
        artist_nationality = "Unknown"
    else:
        title, artist, year, medium, movement, style, subject, color_palette, museum, description, historical_significance, artist_gender, artist_nationality = raw[:13]

    period = period_from_year(year)

    tags = []
    tags.extend(style[:4])
    tags.extend(subject[:3])
    tags.append(movement.split("/")[0].strip().lower())
    tags.append(period.lower().split(" ")[0])
    tags = list(dict.fromkeys(t.lower() for t in tags))[:12]

    return {
        "id": idx_offset,
        "title": title,
        "artist": artist,
        "year": year,
        "medium": medium,
        "movement": movement,
        "style": style,
        "subject": subject,
        "color_palette": color_palette if isinstance(color_palette, list) else [color_palette],
        "museum": museum,
        "description": description,
        "historical_significance": historical_significance,
        "artist_gender": artist_gender,
        "artist_nationality": artist_nationality,
        "period": period,
        "tags": tags,
    }


def main():
    # Load existing artworks
    with open(DATA_PATH, "r", encoding="utf-8") as f:
        existing = json.load(f)

    # Patch existing entries with gender, nationality, and period
    for artwork in existing:
        patch = PATCHES.get(artwork["title"], {})
        artwork.setdefault("artist_gender", patch.get("artist_gender", "unknown"))
        artwork.setdefault("artist_nationality", patch.get("artist_nationality", "Unknown"))
        artwork.setdefault("period", period_from_year(artwork.get("year", 0)))

    # Build new entries
    new_entries = []
    start_id = max(a["id"] for a in existing) + 1
    for i, raw in enumerate(NEW_ARTWORKS_RAW):
        try:
            entry = make_entry(start_id + i, raw)
            new_entries.append(entry)
        except Exception as e:
            print(f"  Skipped entry {i} ({raw[0] if raw else '?'}): {e}")

    merged = existing + new_entries
    with open(DATA_PATH, "w", encoding="utf-8") as f:
        json.dump(merged, f, ensure_ascii=False, indent=2)

    print(f"Done. {len(existing)} existing + {len(new_entries)} new = {len(merged)} total artworks.")


if __name__ == "__main__":
    main()
